from __future__ import annotations


def _to_cents(x: float) -> int:
    return int(round(x * 100))


def _to_float(c: int) -> float:
    return c / 100.0


class Group:
    def __init__(self, members: list[str]) -> None:
        # preserve member order but deduplicate
        seen = set()
        ordered = []
        for m in members:
            if m not in seen:
                seen.add(m)
                ordered.append(m)
        self._members = ordered
        self._member_set = set(ordered)
        # balances in cents
        self._balances: dict[str, int] = {m: 0 for m in ordered}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if payer not in self._member_set:
            raise ValueError(f"Payer {payer!r} is not a group member")
        if participants is None:
            parts = list(self._members)
        else:
            parts = list(participants)
            for p in parts:
                if p not in self._member_set:
                    raise ValueError(f"Participant {p!r} is not a group member")
        total = _to_cents(amount)
        if total < 0:
            raise ValueError("Amount must be non-negative")
        if not parts:
            return

        n = len(parts)
        base = total // n  # each participant's share in cents (rounded down)
        leftover = total - base * n  # cents borne by payer

        # Payer paid `total` cents on behalf of participants.
        self._balances[payer] += total

        if payer in parts:
            # Payer is also a participant: payer is responsible for `base`
            # cents as their own share (leftover is borne by payer implicitly).
            # Every other participant owes exactly `base`.
            for p in parts:
                if p != payer:
                    self._balances[p] -= base
            # Payer's own share: payer owes themselves `base` — cancel it out.
            self._balances[payer] -= base
        else:
            # Payer not participating: every participant owes `base`.
            # Leftover is borne by payer (i.e., payer absorbs it).
            for p in parts:
                self._balances[p] -= base
            # payer covers leftover: reduce payer's credit by leftover
            self._balances[payer] -= leftover

    def balances(self) -> dict[str, float]:
        return {m: _to_float(self._balances[m]) for m in self._members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        # Work in cents. Greedy: pair largest debtor with largest creditor.
        thresholds = 1.00
        debtors = []   # (member, amount_owed_in_cents as positive)
        creditors = [] # (member, amount_owed_to_them_in_cents as positive)
        for m in self._members:
            b = self._balances[m]
            if b > 0:
                creditors.append([m, b])
            elif b < 0:
                debtors.append([m, -b])

        results: list[tuple[str, str, float]] = []
        i = 0
        j = 0
        while i < len(debtors) and j < len(creditors):
            d_member, d_amt = debtors[i]
            c_member, c_amt = creditors[j]
            pay = d_amt if d_amt < c_amt else c_amt
            if _to_float(pay) >= thresholds - 1e-9:
                results.append((d_member, c_member, _to_float(pay)))
            d_amt -= pay
            c_amt -= pay
            debtors[i][1] = d_amt
            creditors[j][1] = c_amt
            if d_amt == 0:
                i += 1
            if c_amt == 0:
                j += 1

        # Ensure at most (members - 1) payments — greedy already satisfies
        # this since each step zeroes out at least one party.
        return results
